import manifest from "./atlas.json";

/**
 * Where each texture sits in public/atlas.png. Generated by
 * `npm run atlas` from assets/textures; do not edit atlas.json by hand.
 */
export interface AtlasManifest {
  tileSize: number;
  columns: number;
  rows: number;
  /** Texture name to [column, row], row 0 at the top of the image. */
  tiles: Record<string, [number, number]>;
}

export const ATLAS = manifest as unknown as AtlasManifest;

export interface UvRect {
  u0: number;
  v0: number;
  u1: number;
  v1: number;
}

/**
 * UV rectangle of a texture; v follows three.js (0 at the image bottom).
 * Inset by half a texel so edges never sample the neighbouring tile.
 */
export function tileUvs(atlas: AtlasManifest, name: string): UvRect {
  const tile = atlas.tiles[name];
  if (tile === undefined) {
    throw new Error(`texture "${name}" is not in the atlas`);
  }
  const [column, row] = tile;
  const insetU = 0.5 / (atlas.tileSize * atlas.columns);
  const insetV = 0.5 / (atlas.tileSize * atlas.rows);
  return {
    u0: column / atlas.columns + insetU,
    u1: (column + 1) / atlas.columns - insetU,
    v0: 1 - (row + 1) / atlas.rows + insetV,
    v1: 1 - row / atlas.rows - insetV,
  };
}
